"BS-Roformer ep317 (SDR 12.97): vocals and instrumental, about 4 minutes for 7": "BS-Roformer ep317（SDR 12.97）：人声和伴奏，7 分钟的歌约 4 分钟",
"Split: vocals + instrumental": "分离：人声 + 伴奏",
