"Cleanup": "清理",
"The start fades in and the end fades out over this many seconds. 0: no fade.": "开头在这么多秒内淡入，结尾淡出。0：不淡入淡出。",
"Fade in and out, s": "淡入淡出，秒",
"Seconds cut off the start, before anything else. 0: from the start.": "在其他处理之前从开头剪掉的秒数。0：从头开始。",
"Trim start, s": "剪掉开头，秒",
"Trim end at, s": "结尾剪到，秒",
"0: to the end": "0：到结尾",
"De-ess": "去齿音",
"De-ess strength": "去齿音强度",
"How strongly: subtle, or normal for a sharper voice.": "强度：轻微，或对更尖的嗓音用普通。",
"Retune from 440 to 432 Hz (pitch and tempo together). Off keeps 440 Hz, for the public.": "从 440 重新调音到 432 Hz（音高和速度一起）。关闭则保持 440 Hz，面向公众。",
"Brings the song to the loudness below: measured first, then set in a second pass. Off: the level stays as it came.": "把歌曲调到下面的响度：先测量，再在第二遍中设定。关闭：电平保持原样。",
"Loudness": "响度",
"The ceiling for the peaks between samples. −1 leaves room for the MP3 and AAC encoders, which add peaks of their own.": "采样间峰值的上限。−1 为会自行添加峰值的 MP3 和 AAC 编码器留出余量。",
"Also an MP3 at 320 kbps, beside the WAV and the FLAC.": "在 WAV 和 FLAC 之外再输出一个 320 kbps 的 MP3。",
"also MP3": "同时输出 MP3",
"What is upscaled: the take, or any file made from it but an upscaled one.": "要超分的对象：录音，或由它生成的任何文件（已超分过的除外）。",
"Mode": "模式",
"how deep it redraws": "重绘的深度",
"Subtle — above 12 kHz": "轻微 —— 12 kHz 以上",
