"High — above 6 kHz": "高 —— 6 kHz 以上",
"Extreme — above 4 kHz": "极致 —— 4 kHz 以上",
"How many versions to draw: they differ only by the noise, and each takes as long as the first. Two let you pick by ear.": "要绘制几个版本：它们只在噪声上不同，每个都和第一个一样耗时。两个就能让你凭耳朵挑选。",
"Variants": "变体",
"Keep the original below the cutoff": "截止频率以下保留原声",
"What is debuzzed: the take, or a file made from it that is neither debuzzed nor upscaled.": "要去嗡声的对象：录音，或由它生成的、既未去过嗡声也未超分过的文件。",
"Strength": "强度",
"How much of the frame ripple to divide out. Viktor's ear: 100 % thinned the opening, 80 % was right.": "把多少帧波动除掉。Viktor 的耳朵：100 % 让开头变薄，80 % 刚好。",
"Which file is measured: the take, or any file made from it.": "要测量的文件：录音，或由它生成的任何文件。",
"Inspect": "检查",
"Where the sound sits: spectrogram, average spectrum, band energy. Lay another take over it to compare.": "声音的位置：频谱图、平均频谱、频段能量。叠加另一个录音来比较。",
"Log": "对数",
"Linear": "线性",
"Lays a second spectrum under this one, on the same scale: a file made from this take, or another take.": "在这个频谱下面以相同刻度叠加第二个频谱：由这个录音生成的文件，或另一个录音。",
"Compare with": "对比对象",
