"How wide the adapter's change is: 16 for one voice or instrument, 32 for a style, 64 for many voices, 128 at most.": "适配器改变的幅度：一个人声或乐器用 16，一种风格用 32，多种人声用 64，最多 128。",
"Whether the music half learns (the part that writes the song's tokens), and how hard its lesson pulls against the anchor: 0 leaves it as the base, a timbre only; raise it for diction and style. What counts is the anchor's share of it, not its size.": "音乐一半（写歌曲 token 的部分）是否学习，以及它的学习对锚点的拉力有多大：0 让它保持基础模型，只学音色；要学咬字和风格就调高。重要的是锚点所占的比例，而不是它的大小。",
"Pulls the music half back toward the base model, so it keeps what the set does not show. Read it as a share of the AR weight: a tenth lets it move, as much as the weight holds it near the base. Nothing at AR weight 0.": "把音乐一半拉回基础模型，让它保留数据集没展示的东西。把它看作 AR 权重的一个比例：十分之一让它可以移动，与权重相同则把它固定在基础附近。AR 权重为 0 时无作用。",
"The music half's learning rate as a share of the one above: the knob that makes it learn faster or slower (0.5: half as fast). It learns a small set by heart quickly.": "音乐一半的学习率，按上面那个的比例：让它学得更快或更慢的设置（0.5：慢一半）。小数据集它很快就会背下来。",
