"Restoring brings back the copy published on Hugging Face: the takes it lacks come again, titles and notes return to the published ones, and what was added to it leaves the workspace (those takes stay in the library; its own sections stay). To keep yours as it is: Cancel, rename your workspace (the ⋯ beside its name, then Rename…), and Get again: the original comes in beside it under its own name.": "恢复会带回 Hugging Face 上发布的副本：缺少的录音会回来，标题和备注恢复为发布时的样子，后来加入的东西会离开工作区（那些录音留在库中；它自己的分区保留）。想保留你自己的版本：取消，给你的工作区改名（名字旁的 ⋯，再选“重命名…”），然后再次获取：原版会以自己的名字放在旁边。",
