"Artwork for “{0}” waits in the queue for a card with room; it starts by itself (Engine → GPUs says which card does what)": "“{0}”的封面图在队列中等待有空间的显卡；会自动开始（引擎 → GPU 说明每张卡做什么）",
"Artwork for “{0}” waits in the queue: {1}. It starts by itself when a card has room": "“{0}”的封面图在队列中等待：{1}。有显卡空出时会自动开始",
