"Show disliked": "显示点踩的",
"The disliked ones too": "点踩的也显示",
"A dislike hides a take from the lists, as SUNO does; nothing is deleted. Ticked, the disliked show too; the 👎 chip shows only them": "点踩会像 SUNO 那样把录音从列表中隐藏；不删除任何东西。勾选后点踩的也显示；👎 标签只显示它们",
"“{0}” disliked: it leaves the lists; nothing is deleted (“Show disliked” brings it back)": "已点踩“{0}”：它离开列表；不删除任何东西（“显示点踩的”可找回）",
"Warning": "警告",
"Characters: {#0} · tokens: ≈{#1} · with the lyrics: ≈{#2} of {#3}": "字符：{#0} · 令牌：≈{#1} · 含歌词：≈{#2}/{#3}",
"What to expect: YuE2 learned from styles without these, and the engine hands the style over word for word. What the model never saw can come out sung as words, or pull the sound away from the style. Written as the official styles are, the style holds.": "预期：YuE2 是在不含这些内容的风格上学习的，引擎会逐字传递风格。模型从未见过的东西可能会被当作歌词唱出来，或让声音偏离风格。按官方风格那样写，风格就能保持。",
"What to expect: the style, the lyrics, the score and the song share one window of 24,576 tokens; past the budget the score or the song is cut short.": "预期：风格、歌词、乐谱和歌曲共用一个 24,576 令牌的窗口；超出预算时乐谱或歌曲会被截断。",
"The score's and the song's token budgets alone fill the window of 24,576 tokens: nothing is left for the style and the lyrics. Lower max tokens under Score sampling or Music sampling, or Max length.": "乐谱和歌曲的令牌预算本身就占满了 24,576 令牌的窗口：没给风格和歌词留下任何空间。请降低乐谱采样或音乐采样下的最多令牌，或最大时长。",
"Only the liked": "只看点赞的",
"Only the disliked: a dislike hides a take from the lists, as SUNO does (nothing is deleted); this shows them": "只看点踩的：点踩会像 SUNO 那样把录音从列表中隐藏（不删除任何东西）；这里显示它们",
"“{0}” disliked: it leaves the lists; nothing is deleted (the 👎 filter shows it)": "已点踩“{0}”：它离开列表；不删除任何东西（👎 筛选可显示它）",
