"artwork": "封面图",
"Painter": "画师",
"Who paints a take's artwork: the player's, the cards', the MP3's cover. A drawing waits in the queue for a card with room.": "谁来画录音的封面图：播放器的、卡片的、MP3 的封面。绘制会在队列中等待有空间的显卡。",
"Krea 2 Muse paints instruments and scenes far truer than SDXL (the studio's A/B on twelve instruments, 05.10.2026); SDXL is for cards it does not fit": "Krea 2 Muse 画乐器和场景远比 SDXL 真实（工作室在十二种乐器上的 A/B，05.10.2026）；SDXL 用于放不下它的显卡",
