", a fine-tune of": "，微调自",
"(Krea 2 Community License: its pictures pass a content filter); SDXL: CyberRealistic XL by Cyberdelia. Times on an RTX 3090, the prompt and the look-over not counted.": "（Krea 2 Community License：其图片要通过内容过滤）；SDXL：Cyberdelia 的 CyberRealistic XL。时间在 RTX 3090 上测得，不含提示和审看。",
