"Artwork on smaller cards: CyberRealistic XL by Cyberdelia": "小显卡上的封面图：Cyberdelia 的 CyberRealistic XL",
"Drawing artwork for “{0}”: a prompt from its style and words, then the picture (a minute or two)": "正在为“{0}”绘制封面图：先从它的风格和歌词写出提示，再画图（一两分钟）",
"a minute or two on a GPU": "在 GPU 上一两分钟",
