"Direct mode writes no score: choose Full plan or Melody only to plan one": "直接模式不写乐谱：要规划乐谱请选完整规划或仅旋律",
"Clear the form?": "清空表单？",
"Its title, style, lyrics, score and every knob go back to the defaults. The takes stay.": "标题、风格、歌词、乐谱和每个设置都恢复默认。录音保留。",
