"{0} · guidance {1}": "{0} · 引导 {1}",
"With Lightning, Karras, Exponential and KL optimal can paint the subject twice: Simple, Beta, Beta 57, SGM uniform or Bong tangent keep it whole.": "配合 Lightning 时，Karras、Exponential 和 KL optimal 可能把主体画两遍：Simple、Beta、Beta 57、SGM uniform 或 Bong tangent 能保持完整。",
"Without Lightning, Euler SDE paints Qwen soft and hazy: Euler, ER-SDE or RES keep the detail.": "不带 Lightning 时，Euler SDE 会把 Qwen 画得柔软朦胧：Euler、ER-SDE 或 RES 能保留细节。",
