"Any model of openrouter.ai/models, written provider/model; the field offers the whole list as you type, each with its price per million tokens in and out. The quick picks fill it in.": "openrouter.ai/models 中的任意模型，写作 提供方/模型；输入时字段会给出完整列表，每个都附有每百万输入和输出令牌的价格。快速选项会自动填入。",
