"Export all: every document of the Writer, with its versions, the takes made from it and its trash, in one file (a backup)": "全部导出：写作室的每份文档，连同其版本、由它生成的录音和它的回收站，放进一个文件（备份）",
"Import a backup": "导入备份",
"Import a Writer backup: what is missing here comes in; the same is left alone; a document that differs from its namesake here comes in beside it as a copy. Nothing here is written over": "导入写作室备份：这里没有的会加入；相同的保持不动；与这里同名文档不同的会作为副本放在旁边。这里的内容都不会被覆盖",
"A Writer backup to import": "要导入的写作室备份",
"The documents column: drag to widen; ← → from the keyboard; Home or a double click for its own width": "文档栏：拖动加宽；键盘 ← →；Home 或双击恢复原宽度",
