"Filter the takes shown: tick what to look for, and whether a take needs all of it (AND), any of it (OR) or none of it (NOR)": "筛选显示的录音：勾选要查找的内容，并选择录音需全部满足（AND）、满足其一（OR）还是都不满足（NOR）",
