"With what is made from them: also every file made from each take (remasters, stems, upscales, debuzzed files), named after the take.": "连同由它们生成的：还包括由每段录音生成的每个文件（重制母带、分轨、超分、去嗡声文件），以录音命名。",
"Export ZIP: made on Forge, then saved by the browser where you tell it": "导出 ZIP：在 Forge 上生成，然后由浏览器保存到你指定的位置",
