"the official examples counted": "官方示例中的次数",
"it goes onto the clipboard and, where you say, into the Style prompt; a name the Style holds already is marked; a lyrics tag goes onto the clipboard only": "它会进入剪贴板，并在你指定的地方进入风格提示；风格中已有的名称会被标记；歌词标签只进入剪贴板",
"The clipboard did not take it": "剪贴板没有接受",
"Russian · conservative (Viktor's)": "俄语 · 保守（Viktor 的）",
"The Artist's log": "画室的日志",
"Transcribed {0} in {1}. Check the melody under Supply your own score, then write the new lyrics and style.": "已在 {1} 内扒谱 {0}。在“提供你自己的乐谱”下检查旋律，然后写新的歌词和风格。",
"1 take carries a score you can remix.": "1 段录音带有可以混音的乐谱。",
"{#0} takes carry a score you can remix.": "{#0} 段录音带有可以混音的乐谱。",
"Make a song in Full plan or Melody only mode first; Direct mode keeps no score.": "请先用“完整规划”或“仅旋律”模式做一首歌；“直接”模式不保留乐谱。",
"A reference is a PNG, JPEG or WebP picture": "参考图须为 PNG、JPEG 或 WebP 图片",
"The picture could not be read": "无法读取图片",
"Pick a take on the right first": "请先在右侧选择一段录音",
"The prompt its artwork was drawn from": "绘制其封面图时所用的提示",
"A prompt from its title and style: say more of what you see": "根据标题和风格生成的提示：再多描述一些你看到的",
"Put the take's prompt in place of the one written here?": "用录音的提示替换这里写的内容？",
"What is written now goes; each run below keeps its own prompt.": "现在写的内容会被替换；下面的每次运行都保留自己的提示。",
"Put it in": "放入",
